nville Road est le premier tronçon reconstitué du trajet funèbre vers Irishtown.","es":"Tritonville Road es el primer tramo reconstruido del trayecto fúnebre hacia Irishtown."}}}]'::jsonb; expected integer := 12;
begin
 if (select count(*) from public.place_descriptions d join jsonb_to_recordset(p) x(book text,id text,collection text,"noteHash" text,"positionSource" text,"narrativeSource" text,description jsonb) on d.book_id=x.book and d.place_id=x.id and d.collection=x.collection where md5(coalesce(d.note,''))=x."noteHash" and d.position_source_id::text=x."positionSource" and d.narrative_source_id::text is not distinct from x."narrativeSource" and (not (coalesce(d.metadata,'{}'::jsonb) ? 'positionDescription') or d.metadata->'positionDescription'=x.description)) <> expected then raise exception 'A source or summary changed; no updates applied'; end if;
 update public.place_descriptions d set metadata=jsonb_set(coalesce(d.metadata,'{}'::jsonb),'{positionDescription}',x.description,true) from jsonb_to_recordset(p) x(book text,id text,collection text,description jsonb) where d.book_id=x.book and d.place_id=x.id and d.collection=x.collection;
